		me.eventvarchanged_vis_menu_centerCallback = function() {
			if (
				(
					((player.getVariableValue('vis_menu_center') == true))
				)
			) {
				me._menu_center.userData.transitionValue_alpha = 1;
				for (var i = 0; i < me._thumbnail_menu.userData.transitions.length; i++) {
					if (me._thumbnail_menu.userData.transitions[i].property == 'alpha') {
						clearInterval(me._thumbnail_menu.userData.transitions[i].interval);
						me._thumbnail_menu.userData.transitions.splice(i, 1);
						break;
					}
				}
				{
					let transition_alpha = {};
					transition_alpha.property = 'alpha';
					transition_alpha.startTime = Date.now();
					transition_alpha.startAlpha = me._thumbnail_menu.material ? me._thumbnail_menu.material.opacity : me._thumbnail_menu.userData.opacity;
					transition_alpha.interval = setInterval(() => {
						let currentTime = Date.now() - 700;
						let percentDone = 1.0 * (currentTime - transition_alpha.startTime) / 500;
						percentDone = Math.max(percentDone, 0.0);
						percentDone = Math.min(percentDone, 1.0);
						let tfval = (percentDone < 0.5 ? (4 * percentDone * percentDone * percentDone) : (1 - Math.pow(-2 * percentDone + 2, 3) / 2));
						me._thumbnail_menu.userData.setOpacity(transition_alpha.startAlpha + (me._menu_center.userData.transitionValue_alpha - transition_alpha.startAlpha) * tfval);
						player.repaint();
						if (percentDone >= 1.0) {
							clearInterval(transition_alpha.interval);
							me._thumbnail_menu.userData.transitions.splice(me._thumbnail_menu.userData.transitions.indexOf(transition_alpha), 1);
						}
					}, 20);
					me._thumbnail_menu.userData.transitions.push(transition_alpha);
				}
			}
			if (
				(
					((player.getVariableValue('vis_menu_center') == false))
				)
			) {
				me._menu_center.userData.transitionValue_alpha = 0;
				for (var i = 0; i < me._thumbnail_menu.userData.transitions.length; i++) {
					if (me._thumbnail_menu.userData.transitions[i].property == 'alpha') {
						clearInterval(me._thumbnail_menu.userData.transitions[i].interval);
						me._thumbnail_menu.userData.transitions.splice(i, 1);
						break;
					}
				}
				{
					let transition_alpha = {};
					transition_alpha.property = 'alpha';
					transition_alpha.startTime = Date.now();
					transition_alpha.startAlpha = me._thumbnail_menu.material ? me._thumbnail_menu.material.opacity : me._thumbnail_menu.userData.opacity;
					transition_alpha.interval = setInterval(() => {
						let currentTime = Date.now() - 0;
						let percentDone = 1.0 * (currentTime - transition_alpha.startTime) / 200;
						percentDone = Math.max(percentDone, 0.0);
						percentDone = Math.min(percentDone, 1.0);
						let tfval = (percentDone < 0.5 ? (4 * percentDone * percentDone * percentDone) : (1 - Math.pow(-2 * percentDone + 2, 3) / 2));
						me._thumbnail_menu.userData.setOpacity(transition_alpha.startAlpha + (me._menu_center.userData.transitionValue_alpha - transition_alpha.startAlpha) * tfval);
						player.repaint();
						if (percentDone >= 1.0) {
							clearInterval(transition_alpha.interval);
							me._thumbnail_menu.userData.transitions.splice(me._thumbnail_menu.userData.transitions.indexOf(transition_alpha), 1);
						}
					}, 20);
					me._thumbnail_menu.userData.transitions.push(transition_alpha);
				}
			}
			me._menu_center_slider.logicBlock_position();
			me._map.logicBlock_size();
			me._video_popup.logicBlock_size();
			me._url_popup.logicBlock_size();
		};
		player.addListener('varchanged_vis_menu_center', me.eventvarchanged_vis_menu_centerCallback);
